import React, { useEffect, useState } from 'react';
import axiosInstance from "./axiousInstance";
import FeedbackCard from "./FeedbackCard";

const FeedbackSection = ({ masters = [], services = [] }) => {
    const [masterName, setMasterName] = useState('');
    const [serviceName, setServiceName] = useState('');
    const [userName, setUserName] = useState('');
    const [feedbackText, setFeedbackText] = useState('');
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');
    const [feedbackList, setFeedbackList] = useState([]);

    useEffect(() => {
        fetchFeedbacks();
    }, []);

    const fetchFeedbacks = async () => {
        try {
            const response = await axiosInstance.get("/feedback", {
                baseURL: "http://localhost:8080/api"
            });
            setFeedbackList(response.data.reverse());
        } catch (err) {
            console.error("Error loading feedbacks", err);
        }
    };

    const handleSubmit = async () => {
        if (!masterName || !serviceName || !userName || !feedbackText) {
            setMessage("Please fill in all fields.");
            return;
        }

        const feedback = { masterName, serviceName, userName, feedbackText };
        setLoading(true);
        setMessage('');

        try {
            const response = await axiosInstance.post("/feedback", feedback, {
                baseURL: "http://localhost:8080/api"
            });

            if (response.status === 200) {
                setMessage("✅ Feedback submitted successfully!");
                setMasterName('');
                setServiceName('');
                setUserName('');
                setFeedbackText('');
                fetchFeedbacks(); // refresh list
            } else {
                setMessage("❌ Failed to submit feedback. Try again.");
            }
        } catch (err) {
            console.error("Failed to submit feedback", err);
            setMessage("❌ An error occurred. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <section id="feedback" className="container py-5">
            <h2 className="mb-4 text-center">Feedback</h2>

            <div className="row">
                <div className="col-md-6">
                    <img src="/poster1.jpg" alt="Salon" className="img-fluid rounded shadow" />
                </div>

                <div className="col-md-6">
                    <div className="bg-light p-4 rounded shadow-sm">
                        <h4 className="mb-3">Leave your feedback</h4>

                        <label>Choose Master:</label>
                        <select className="form-select mb-2" value={masterName} onChange={(e) => setMasterName(e.target.value)}>
                            <option value="">Select Master</option>
                            {masters.map(master => (
                                <option key={master.id} value={master.name}>{master.name}</option>
                            ))}
                        </select>

                        <label>Choose Service:</label>
                        <select className="form-select mb-2" value={serviceName} onChange={(e) => setServiceName(e.target.value)}>
                            <option value="">Select Service</option>
                            {services.map(service => (
                                <option key={service.id} value={service.name}>{service.name}</option>
                            ))}
                        </select>

                        <label>Your Name:</label>
                        <input
                            type="text"
                            className="form-control mb-2"
                            placeholder="Your Name"
                            value={userName}
                            onChange={(e) => setUserName(e.target.value)}
                        />

                        <label>Your Feedback:</label>
                        <textarea
                            className="form-control mb-3"
                            placeholder="Your Feedback"
                            rows="3"
                            value={feedbackText}
                            onChange={(e) => setFeedbackText(e.target.value)}
                        ></textarea>

                        <button className="btn btn-primary w-100" onClick={handleSubmit} disabled={loading}>
                            {loading ? "Submitting..." : "Submit Feedback"}
                        </button>

                        {message && (
                            <p className="mt-2" style={{ color: message.startsWith("✅") ? "green" : "red" }}>
                                {message}
                            </p>
                        )}
                    </div>
                </div>
            </div>

            <div className="mt-5">
                <h4 className="mb-3">Recent Feedback</h4>
                {feedbackList.length > 0 ? (
                    feedbackList.map((fb) => (
                        <FeedbackCard
                            key={fb.id}
                            feedback={fb.feedbackText}
                            author={fb.userName}
                            date={fb.createdAt}
                        />
                    ))
                ) : (
                    <p>No feedback submitted yet.</p>
                )}
            </div>
        </section>
    );
};

export default FeedbackSection;
